package in.finseq.insurance;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfRenderer;import android.graphics.pdf.content.PdfPageTextContent;import android.os.*;import android.os.ParcelFileDescriptor;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;

public class PdfPreviewActivity extends FinseqActivity{
 static final int SAVE_PDF=781;File cached;PdfRenderer renderer;ParcelFileDescriptor fd;ZoomImageView preview;TextView count,pageText;Button save;String attachmentType="";int pageIndex=0,policyId;
 public void onCreate(Bundle b){super.onCreate(b);policyId=getIntent().getIntExtra("policy_id",0);if(policyId<=0){finish();return;}LinearLayout root=Ui.column(this);Ui.appHeader(root,this,"PDF Preview");LinearLayout body=Ui.contentColumn(this);root.addView(body);count=Ui.sub(this,"Loading PDF…");body.addView(count);
  LinearLayout bar=new LinearLayout(this);bar.setOrientation(LinearLayout.HORIZONTAL);Button prev=Ui.outlineButton(this,"← Previous");Button jump=Ui.outlineButton(this,"Jump");Button next=Ui.outlineButton(this,"Next →");bar.addView(prev,new LinearLayout.LayoutParams(0,-2,1));bar.addView(jump,new LinearLayout.LayoutParams(0,-2,1));bar.addView(next,new LinearLayout.LayoutParams(0,-2,1));body.addView(bar);
  LinearLayout tools=new LinearLayout(this);tools.setOrientation(LinearLayout.HORIZONTAL);Button search=Ui.outlineButton(this,"Search");Button continuous=Ui.outlineButton(this,"Continuous Scroll");Button reset=Ui.outlineButton(this,"Reset Zoom");tools.addView(search,new LinearLayout.LayoutParams(0,-2,1));tools.addView(continuous,new LinearLayout.LayoutParams(0,-2,1));tools.addView(reset,new LinearLayout.LayoutParams(0,-2,1));body.addView(tools);
  body.addView(Ui.sub(this,"Swipe left/right for pages · pinch or double-tap to zoom · selectable page text appears below on supported Android versions."));save=Ui.greenButton(this,"Download attachment");save.setEnabled(false);body.addView(save);preview=new ZoomImageView(this);preview.setBackgroundColor(Color.WHITE);body.addView(preview,new LinearLayout.LayoutParams(-1,(int)(getResources().getDisplayMetrics().heightPixels*0.60f)));
  pageText=Ui.sub(this,"");pageText.setTextIsSelectable(true);pageText.setVisibility(View.GONE);LinearLayout textCard=Ui.card(this);textCard.addView(Ui.text(this,"Selectable text",16,true));textCard.addView(pageText);body.addView(textCard);
  setContentView(Ui.scroll(this,root));prev.setOnClickListener(v->show(pageIndex-1));next.setOnClickListener(v->show(pageIndex+1));jump.setOnClickListener(v->jump());search.setOnClickListener(v->search());continuous.setOnClickListener(v->startActivity(new Intent(this,PdfContinuousActivity.class).putExtra("policy_id",policyId)));reset.setOnClickListener(v->preview.resetZoom());preview.setPageSwipeListener(new ZoomImageView.PageSwipeListener(){public void onNext(){show(pageIndex+1);}public void onPrevious(){show(pageIndex-1);}});
  save.setOnClickListener(v->{if(cached==null||attachmentType.isEmpty())return;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(attachmentType.equals("pdf")?"application/pdf":attachmentType.equals("png")?"image/png":"image/jpeg");i.putExtra(Intent.EXTRA_TITLE,"FINSEQ_Policy_"+policyId+"."+attachmentType);startActivityForResult(i,SAVE_PDF);});
  Ui.run(this,()->{try{final File file=ApiClient.pdf(this,policyId);Ui.ui(this,()->open(file));}catch(final Exception e){Ui.ui(this,()->count.setText("Policy #"+policyId+" · Preview failed: "+e.getMessage()));}});
 }
 void open(File file){try{cached=file;attachmentType=ApiClient.attachmentType(file);save.setEnabled(true);save.setText(attachmentType.equals("pdf")?"Download PDF":"Download image ("+attachmentType.toUpperCase()+")");if(attachmentType.equals("pdf")){fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);renderer=new PdfRenderer(fd);show(0);}else{BitmapFactory.Options size=new BitmapFactory.Options();size.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getAbsolutePath(),size);int sample=1;while(size.outWidth/sample>1600||size.outHeight/sample>2200)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;Bitmap bitmap=BitmapFactory.decodeFile(file.getAbsolutePath(),options);if(bitmap==null)throw new IOException("Image cannot be decoded");preview.setImageBitmap(bitmap);count.setText("Policy image preview · "+attachmentType.toUpperCase());}}catch(OutOfMemoryError e){count.setText("Attachment is too large to preview. Download the original file.");}catch(Exception e){count.setText("Preview unavailable: "+e.getMessage()+". You can still download the original attachment.");}}
 void show(int index){if(renderer==null||index<0||index>=renderer.getPageCount())return;pageIndex=index;try(PdfRenderer.Page page=renderer.openPage(index)){double scale=Math.min(1800.0/page.getWidth(),Math.sqrt(5000000.0/((double)page.getWidth()*page.getHeight())));int width=Math.max(1,(int)(page.getWidth()*scale)),height=Math.max(1,(int)(page.getHeight()*scale));Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);page.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);preview.setImageBitmap(bitmap);preview.resetZoom();count.setText("Page "+(index+1)+" / "+renderer.getPageCount());showSelectableText(page);}catch(OutOfMemoryError e){count.setText("Page is too large to preview on this phone");}catch(Exception e){Ui.toast(this,e.getMessage());}}
 void showSelectableText(PdfRenderer.Page page){if(Build.VERSION.SDK_INT<35){pageText.setText("Text selection inside FINSEQ is available on Android 15+. On older Android versions use Download PDF / your system PDF viewer for text selection.");pageText.setVisibility(View.VISIBLE);return;}try{StringBuilder b=new StringBuilder();for(PdfPageTextContent c:page.getTextContents()){String t=c.getText();if(t!=null&&!t.trim().isEmpty())b.append(t).append('\n');}pageText.setText(b.length()==0?"No embedded text layer on this page (likely a scanned/image PDF).":b.toString().trim());pageText.setVisibility(View.VISIBLE);}catch(Exception e){pageText.setText("Text layer unavailable on this page.");pageText.setVisibility(View.VISIBLE);}}
 void jump(){if(renderer==null)return;EditText input=Ui.input(this,"Page 1 - "+renderer.getPageCount());input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);new AlertDialog.Builder(this).setTitle("Jump to page").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Go",(d,w)->{try{int p=Integer.parseInt(input.getText().toString().trim());if(p<1||p>renderer.getPageCount())throw new Exception();show(p-1);}catch(Exception e){Ui.toast(this,"Enter a page between 1 and "+renderer.getPageCount());}}).show();}
 void search(){if(renderer==null)return;EditText input=Ui.input(this,"Search text in PDF");new AlertDialog.Builder(this).setTitle("Search inside PDF").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Search",(d,w)->searchText(input.getText().toString().trim())).show();}
 void searchText(String q){if(q.isEmpty())return;if(Build.VERSION.SDK_INT<35){Ui.toast(this,"In-app PDF text search requires Android 15+. You can download/open the PDF in your system viewer on older Android versions.");return;}count.setText("Searching for “"+q+"”…");Ui.run(this,()->{int found=-1;try{for(int i=0;i<renderer.getPageCount();i++){try(PdfRenderer.Page p=renderer.openPage(i)){for(PdfPageTextContent c:p.getTextContents()){if(c.getText()!=null&&c.getText().toLowerCase(Locale.ROOT).contains(q.toLowerCase(Locale.ROOT))){found=i;break;}}}if(found>=0)break;}}catch(Exception ignored){}final int page=found;Ui.ui(this,()->{if(page>=0){show(page);Ui.toast(this,"Found on page "+(page+1));}else{count.setText("No match for “"+q+"”");}});});}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=SAVE_PDF||result!=RESULT_OK||data==null||data.getData()==null||cached==null)return;try(InputStream in=new FileInputStream(cached);OutputStream out=getContentResolver().openOutputStream(data.getData())){byte[] buffer=new byte[1024*1024];int size;while((size=in.read(buffer))!=-1)out.write(buffer,0,size);Ui.toast(this,"Policy attachment saved");}catch(Exception e){Ui.toast(this,"Could not save attachment: "+e.getMessage());}}
 protected void onDestroy(){super.onDestroy();try{if(renderer!=null)renderer.close();if(fd!=null)fd.close();}catch(IOException ignored){}if(cached!=null)cached.delete();}
}
